  // ---- Uploading ----
  "The upload failed. Please try again.": ["上传失败，请重试。", "अपलोड विफल रहा। कृपया फिर कोशिश करें।", "La subida falló. Inténtalo de nuevo.", "فشل الرفع. يرجى المحاولة مجددًا.", "L'envoi a échoué. Veuillez réessayer.", "আপলোড ব্যর্থ হয়েছে। আবার চেষ্টা করুন।", "O envio falhou. Tente de novo.", "Загрузка не удалась. Попробуйте снова.", "اپ لوڈ ناکام ہو گیا۔ براہ کرم دوبارہ کوشش کریں۔", "上載失敗，請再試。", "Unggahan gagal. Silakan coba lagi."],
  "The connection dropped during the upload.": ["上传过程中连接中断。", "अपलोड के दौरान कनेक्शन टूट गया।", "La conexión se cortó durante la subida.", "انقطع الاتصال أثناء الرفع.", "La connexion a été coupée pendant l'envoi.", "আপলোডের সময় সংযোগ বিচ্ছিন্ন হয়েছে।", "A conexão caiu durante o envio.", "Соединение прервалось во время загрузки.", "اپ لوڈ کے دوران کنکشن ٹوٹ گیا۔", "上載期間斷咗線。", "Koneksi terputus saat mengunggah."],
  "The upload was cancelled.": ["上传已取消。", "अपलोड रद्द कर दिया गया।", "Se canceló la subida.", "تم إلغاء الرفع.", "L'envoi a été annulé.", "আপলোড বাতিল করা হয়েছে।", "O envio foi cancelado.", "Загрузка отменена.", "اپ لوڈ منسوخ کر دیا گیا۔", "上載已取消。", "Unggahan dibatalkan."],
  "Choose up to 30 photos at a time.": ["每次最多选择 30 张照片。", "एक बार में ज़्यादा से ज़्यादा 30 फ़ोटो चुनें।", "Elige hasta 30 fotos a la vez.", "اختر حتى 30 صورة في كل مرة.", "Choisissez jusqu'à 30 photos à la fois.", "একবারে সর্বোচ্চ ৩০টি ছবি বেছে নিন।", "Escolha até 30 fotos por vez.", "Выбирайте не больше 30 фото за раз.", "ایک وقت میں زیادہ سے زیادہ 30 تصاویر چنیں۔", "每次最多揀 30 張相。", "Pilih hingga 30 foto sekaligus."],
