  "%1 photos recovered": ["已恢复 %1 张照片", "%1 फ़ोटो वापस आ गईं", "%1 fotos recuperadas", "تمت استعادة %1 صور", "%1 photos récupérées", "%1টি ছবি পুনরুদ্ধার হয়েছে", "%1 fotos recuperadas", "Восстановлено фото: %1", "%1 تصاویر بحال ہو گئیں", "已還原 %1 張相", "%1 foto dipulihkan"],
  "Back in their albums.": ["已回到所在的相册。", "अपने एल्बम में वापस।", "De vuelta en sus álbumes.", "عادت إلى ألبوماتها.", "De retour dans leurs albums.", "নিজেদের অ্যালবামে ফিরে গেছে।", "De volta aos álbuns.", "Снова в своих альбомах.", "اپنے البمز میں واپس۔", "返咗去原本嘅相簿。", "Kembali ke albumnya."],
  "Photo deleted for good": ["照片已永久删除", "फ़ोटो हमेशा के लिए हटा दी गई", "Foto eliminada para siempre", "حُذفت الصورة نهائيًا", "Photo supprimée définitivement", "ছবি চিরতরে মুছে ফেলা হয়েছে", "Foto excluída de vez", "Фото удалено навсегда", "تصویر ہمیشہ کے لیے حذف ہو گئی", "相已永久刪除", "Foto dihapus selamanya"],
  "%1 photos deleted for good": ["已永久删除 %1 张照片", "%1 फ़ोटो हमेशा के लिए हटा दी गईं", "%1 fotos eliminadas para siempre", "حُذفت %1 صور نهائيًا", "%1 photos supprimées définitivement", "%1টি ছবি চিরতরে মুছে ফেলা হয়েছে", "%1 fotos excluídas de vez", "Удалено навсегда фото: %1", "%1 تصاویر ہمیشہ کے لیے حذف ہو گئیں", "已永久刪除 %1 張相", "%1 foto dihapus selamanya"],
  "Photo shown again": ["照片已重新显示", "फ़ोटो फिर से दिखाई गई", "Foto visible de nuevo", "ظهرت الصورة مجددًا", "Photo réaffichée", "ছবি আবার দেখানো হয়েছে", "Foto visível de novo", "Фото снова видно", "تصویر دوبارہ دکھائی گئی", "相已重新顯示", "Foto ditampilkan lagi"],
  "%1 photos shown again": ["已重新显示 %1 张照片", "%1 फ़ोटो फिर से दिखाई गईं", "%1 fotos visibles de nuevo", "ظهرت %1 صور مجددًا", "%1 photos réaffichées", "%1টি ছবি আবার দেখানো হয়েছে", "%1 fotos visíveis de novo", "Снова видно фото: %1", "%1 تصاویر دوبارہ دکھائی گئیں", "已重新顯示 %1 張相", "%1 foto ditampilkan lagi"],
  "Back in the album for you.": ["已在你的相册中恢复显示。", "आपके लिए एल्बम में वापस।", "De vuelta en el álbum para ti.", "عادت إلى الألبوم لديك.", "De retour dans l'album pour vous.", "আপনার জন্য অ্যালবামে ফিরে এসেছে।", "De volta ao álbum para você.", "Снова в альбоме у вас.", "آپ کے لیے البم میں واپس۔", "喺你嘅相簿度重新顯示。", "Kembali ke album untuk Anda."],

